// Writes apps/worker/src/build-info.generated.ts with the identity of this build:
// the Git commit it was built from and a unique ID per build, so every commit and
// every deployment yields a different version string. The output is gitignored and
// regenerated by the worker's build, dev, test and deploy scripts.
import { execFileSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const GIT_BINARY = "git";
const UNKNOWN_COMMIT = "unknown";
const SHORT_COMMIT_LENGTH = 12;
const OUTPUT_PATH = fileURLToPath(new URL("../apps/worker/src/build-info.generated.ts", import.meta.url));
const PACKAGE_PATH = fileURLToPath(new URL("../apps/worker/package.json", import.meta.url));

function runGit(args) {
  return execFileSync(GIT_BINARY, args, { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
}

// Falls back to "unknown" outside a Git checkout (for example a source tarball) and says so,
// so a build without commit information is visible rather than silently mislabelled.
function readCommit() {
  try {
    return runGit(["rev-parse", "HEAD"]);
  } catch (error) {
    process.stderr.write(`generate-build-info: cannot read Git HEAD (${String(error)}); using "${UNKNOWN_COMMIT}".\n`);
    return UNKNOWN_COMMIT;
  }
}

function readDirty(commit) {
  if (commit === UNKNOWN_COMMIT) return false;
  return runGit(["status", "--porcelain", "--untracked-files=no"]).length > 0;
}

const packageVersion = JSON.parse(readFileSync(PACKAGE_PATH, "utf8")).version;
const commit = readCommit();
const dirty = readDirty(commit);
const buildId = randomUUID();
const builtAt = new Date().toISOString();
const shortCommit = commit.slice(0, SHORT_COMMIT_LENGTH);
// SemVer build metadata: "<package version>+<commit>.<build id>", with dirty trees marked.
const version = `${packageVersion}+${shortCommit}${dirty ? ".dirty" : ""}.${buildId}`;

const source = `// Generated by scripts/generate-build-info.mjs. Do not edit; this file is gitignored.
export const BUILD_INFO = {
  version: ${JSON.stringify(version)},
  commit: ${JSON.stringify(commit)},
  dirty: ${dirty},
  buildId: ${JSON.stringify(buildId)},
  builtAt: ${JSON.stringify(builtAt)},
} as const;
`;

writeFileSync(OUTPUT_PATH, source);
process.stdout.write(`generate-build-info: ${version}\n`);
